class ContentTypeRelabelError(Exception):
    pass


def _relabel(apps, old, new):
    ContentType = apps.get_model("contenttypes", "ContentType")
    for model in MOVED_MODELS:
        key = model.lower()
        old_rows = list(ContentType.objects.filter(app_label=old, model=key))
        new_rows = list(ContentType.objects.filter(app_label=new, model=key))
        if len(old_rows) > 1 or len(new_rows) > 1:
            raise ContentTypeRelabelError(f"duplicate content types for {key}")
        if old_rows and new_rows:
            raise ContentTypeRelabelError(
                f"content type for {key} exists under both {old} and {new}; "
                "resolve manually before migrating"
            )
        if old_rows:
            ContentType.objects.filter(pk=old_rows[0].pk).update(app_label=new)
        # neither row: fresh database, post_migrate will create it under `new`.
    remaining = ContentType.objects.filter(
        app_label=old, model__in=[m.lower() for m in MOVED_MODELS]
    ).count()
    if remaining:
        raise ContentTypeRelabelError(f"{remaining} content types still under {old}")


def relabel_content_types_forward(apps, schema_editor):
    _relabel(apps, "emr", "care_suriname")


def relabel_content_types_backward(apps, schema_editor):
    _relabel(apps, "care_suriname", "emr")


